<?php require 'config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify();$s=$db->prepare('SELECT * FROM users WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);$_SESSION['id']=$u['id'];$_SESSION['role']=$u['role'];$_SESSION['name']=$u['name'];go('index.php');}$error='Invalid login.';}head('Login');?><section class="form"><h1>Login</h1><p><?=h($error)?></p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button>Login</button></form></section><?php foot();?>
